# Writes the hedra command files of the fishing pier: pier.txt, rod.txt, lure.txt, fish_s/m/l.txt,
# jelly.txt, waves.txt (a strip of wave crests the game slides), seabed.txt, kelp.txt, rock.txt,
# island.txt (an islet with a lighthouse on the horizon), sun.txt, cloud.txt, splash.txt, bubbles.txt.
# Run from models/env: /usr/bin/python3 make_env.py. hedra: up Z, front -Y (the camera side;
# glTF z = -hedra y). Colours exact Pollen8.
import math, random

C = {"plum": "0.451 0.275 0.298", "berry": "0.671 0.337 0.459", "rose": "0.933 0.416 0.486",
     "pink": "1.000 0.655 0.647", "gold": "1.000 0.878 0.494", "cream": "1.000 0.906 0.839",
     "mint": "0.447 0.863 0.733", "teal": "0.204 0.675 0.729"}
def mat(name, col, emit=False):
    s = f"material new {name} --base-color {C[col]} --no-slot"
    return s + (f" --emission {C[col]}" if emit else "")
def box(name, x, y, z, sx, sy, sz, m, rot=None):
    r = f" --rotation {rot}" if rot else ""
    return [f"add mesh cube --name {name} --size 1 --location {x:.3f} {y:.3f} {z:.3f}{r}",
            f"scale {sx:.3f} {sy:.3f} {sz:.3f}", "apply --scale", f"material assign {m}"]

# ---- pier: a deck 4.2 m long from off the left edge to x -3.5, its top 0.9 above the water, on piles
# down to the seabed (-5.6); a railing along its back, a lamp post. Origin at the water line.
p = ["# The pier: a plank deck (glTF x -7.7..-3.5, top y 0.9, z -1.1..0.7), piles down to the seabed,",
     "# a railing along its back edge, a lamp post. Generated by make_env.py.", "new",
     mat("Wood", "berry"), mat("Dark", "plum"), mat("Seam", "plum"), mat("Lamp", "gold", True)]
p += box("Deck", -5.6, 0.2, 0.8, 4.2, 1.8, 0.2, "Wood")
for i, x in enumerate([-7.3, -5.5, -3.75]):
    p += box(f"PileF{i}", x, -0.55, -2.4, 0.26, 0.26, 6.4, "Dark")
    p += box(f"PileB{i}", x, 1.0, -2.4, 0.26, 0.26, 6.4, "Dark")
# planks: thin dark gaps on the deck's front face read as plank ends (proud by a spacing)
for i in range(8):
    x = -7.55 + i * 0.52
    p += box(f"Gap{i}", x, -0.72, 0.8, 0.07, 0.06, 0.2, "Seam")
for i, x in enumerate([-7.4, -6.3, -5.2, -4.1]):
    p += box(f"Post{i}", x, 0.95, 1.25, 0.12, 0.12, 0.7, "Wood")
p += box("Rail", -5.75, 0.95, 1.55, 3.6, 0.1, 0.1, "Wood")
p += box("LampPost", -6.85, 0.9, 1.95, 0.12, 0.12, 2.1, "Dark")
p += box("LampArm", -6.68, 0.9, 2.95, 0.4, 0.08, 0.08, "Dark")
p += box("Lantern", -6.5, 0.9, 2.78, 0.22, 0.22, 0.28, "Lamp")
p += ["select all", "shade flat", "export pier.glb"]
open("pier.txt", "w").write("\n".join(p) + "\n")

# ---- rod: from the handle (origin, the pivot) along +X tilted up 18 degrees, 2.8 m, tapering
open("rod.txt", "w").write(f"""# The rod: a 2.8 m pole from the handle (origin: the pivot the game bends it about) along +X, tilted
# up 18 degrees, a cork grip and a reel at the handle. Generated by make_env.py.
new
{mat("Rod", "plum")}
{mat("Grip", "rose")}
add mesh cube --name Rod --size 1 --location 1.4 0 0
scale 2.8 0.08 0.08
apply --scale
active Rod
mode edit
select vert where "pos.x > 1.0"
scale 1 0.7 0.7
mode object
material assign Rod
add mesh cube --name Grip --size 1 --location 0.05 0 0
scale 0.5 0.12 0.12
apply --scale
material assign Grip
add mesh cylinder --name Reel --vertices 6 --radius 0.1 --depth 0.08 --location 0.25 0 -0.1 --rotation 90 0 0
material assign Rod
select all
set rotation 0 -18 0
apply --rotation
shade flat
export rod.glb
""")

# ---- lure: a gold bobber-like lure with a plum hook under it (origin at its top: the line's end)
open("lure.txt", "w").write(f"""# The lure on the line's end: a gold ball 0.26 m with a plum hook below; origin at its top.
# Generated by make_env.py.
new
{mat("Gold", "gold")}
{mat("Hook", "plum")}
add mesh ico-sphere --name Ball --subdivisions 1 --radius 0.13 --location 0 0 -0.13
material assign Gold
add mesh cube --name Shank --size 1 --location 0 0 -0.33
scale 0.07 0.07 0.2
apply --scale
material assign Hook
add mesh cube --name Barb --size 1 --location 0.07 0 -0.42
scale 0.14 0.07 0.07
apply --scale
material assign Hook
select all
shade flat
export lure.glb
""")

# ---- fish: a faceted body, a tail, a dorsal fin, an eye on each side; facing -Y (the glTF +Z the game
# turns to +-X). Three kinds: small gold, middling rose, big plum (deep).
for name, L, body, fin, scale in [("fish_s", 0.7, "gold", "rose", 1.0), ("fish_m", 0.9, "pink", "rose", 1.0),
                                  ("fish_l", 1.3, "berry", "plum", 1.0)]:
    h = L * 0.42; w = L * 0.24
    f = [f"# A fish {L} m long (glTF facing +Z): body, tail, dorsal fin, eyes. Generated by make_env.py.", "new",
         mat("Body", body), mat("Fin", fin), mat("Eye", "plum"),
         f"add mesh ico-sphere --name Body --subdivisions 1 --radius 0.5 --location 0 0 0",
         f"scale {w:.3f} {L * 0.78:.3f} {h:.3f}", "apply --scale", "material assign Body",
         f"add mesh cone --name Tail --vertices 4 --radius1 {h * 0.55:.3f} --radius2 0.02 --depth {L * 0.32:.3f} --location 0 {L * 0.47:.3f} 0 --rotation -90 45 0",
         "scale 1 1 1", "material assign Fin",
         f"add mesh cone --name Dorsal --vertices 4 --radius1 {L * 0.16:.3f} --radius2 0.01 --depth {h * 0.45:.3f} --location 0 {L * 0.05:.3f} {h * 0.55:.3f} --rotation 0 0 45",
         "scale 0.35 1.4 1", "material assign Fin",
         f"add mesh cube --name EyeL --size {max(0.07, L * 0.09):.3f} --location {w * 0.42:.3f} {-L * 0.26:.3f} {h * 0.08:.3f}",
         "material assign Eye",
         f"add mesh cube --name EyeR --size {max(0.07, L * 0.09):.3f} --location {-w * 0.42:.3f} {-L * 0.26:.3f} {h * 0.08:.3f}",
         "material assign Eye", "select all", "shade flat", f"export {name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(f) + "\n")

# ---- jellyfish: a faceted dome and four tentacles, unlit (it glows); origin at the dome's middle
open("jelly.txt", "w").write(f"""# A jellyfish: a faceted pink dome 0.7 m across, a cream rim, four tentacles 0.6 m. Origin at the
# dome's base (the game pulses it). Unlit. Generated by make_env.py.
new
{mat("Dome", "pink", True)}
{mat("Frill", "cream", True)}
add mesh ico-sphere --name Dome --subdivisions 1 --radius 0.36 --location 0 0 0
scale 1 1 0.8
apply --scale
active Dome
mode edit
select vert where "pos.z < -0.05"
scale 1 1 0.1
mode object
material assign Dome
add mesh cylinder --name Rim --vertices 8 --radius 0.38 --depth 0.08 --location 0 0 -0.02
material assign Frill
add mesh cube --name T0 --size 1 --location 0.18 0 -0.33
scale 0.08 0.08 0.6
add mesh cube --name T1 --size 1 --location -0.18 0 -0.38
scale 0.08 0.08 0.7
add mesh cube --name T2 --size 1 --location 0.05 0.12 -0.42
scale 0.08 0.08 0.8
add mesh cube --name T3 --size 1 --location -0.05 -0.12 -0.3
scale 0.08 0.08 0.55
select T0 T1 T2 T3
apply --scale
material assign Frill
select all
shade flat
export jelly.glb
""")

# ---- waves: a strip of wave crests 20 m long (a 1.25 m period), sliding along x one period per loop
# in the game. Front strip mint over cream foam.
def waves(name, col_a, col_b, height, period=1.25, length=20.0):
    w = [f"# Wave crests: a strip {length:.0f} m long, crests every {period} m, {height} m high; the game slides it",
         "# one period and wraps. Origin at the water line. Generated by make_env.py.", "new",
         mat("Crest", col_a), mat("Foam", col_b)]
    n = int(length / period)
    names = []
    for i in range(n):
        x = -length / 2 + (i + 0.5) * period
        w += [f"add mesh cone --name W{i} --vertices 4 --radius1 {period * 0.62:.3f} --radius2 0.0 --depth {height:.3f} --location {x:.3f} 0 {-height * 0.25:.3f} --rotation 0 0 45",
              "scale 1 0.35 1", "apply --scale", "material assign Crest"]
        w += [f"add mesh cube --name F{i} --size 1 --location {x:.3f} -0.05 {height * 0.18:.3f}",
              f"scale {period * 0.3:.3f} 0.12 0.09", "apply --scale", "material assign Foam"]
        names += [f"W{i}", f"F{i}"]
    w += ["select all", "shade flat", f"export {name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(w) + "\n")
waves("waves", "mint", "cream", 0.36)
waves("swell", "teal", "mint", 0.28, period=1.6)

# ---- seabed: a sand bank along the bottom with lumps, from x -9 to 9
rnd = random.Random(4)
s = ["# Seabed: a sand floor (top near y -5.45) 18 m wide, 3 m deep, lumpy. Generated by make_env.py.", "new",
     mat("Sand", "berry"),
     "add mesh grid --name Floor --x-subdivisions 18 --y-subdivisions 3 --size 1 --location 0 0 -5.45",
     "scale 18 3 1", "apply --scale", "material assign Sand", "active Floor", "mode edit",
     "select all", "randomize --amount 0.12 --seed 2", "mode object",
     "add mesh cube --name Front --size 1 --location 0 -1.5 -5.85", "scale 18 0.05 0.8", "apply --scale", "material assign Sand"]
for i in range(9):
    x = -8 + i * 2 + rnd.uniform(-0.5, 0.5)
    s += [f"add mesh ico-sphere --name Lump{i} --subdivisions 1 --radius {rnd.uniform(0.3, 0.55):.2f} --location {x:.2f} {rnd.uniform(-1.0, 0.8):.2f} -5.45",
          "scale 1.6 1 0.6", "apply --scale", "material assign Sand"]
s += ["select all", "shade flat", "export seabed.glb"]
open("seabed.txt", "w").write("\n".join(s) + "\n")

open("rock.txt", "w").write(f"""# A seabed rock 1.1 m, plum with a rose top. Generated by make_env.py.
new
{mat("Rock", "plum")}
{mat("Top", "berry")}
add mesh ico-sphere --name Rock --subdivisions 1 --radius 0.55 --location 0 0 0.2 --rotation 15 25 40
scale 1.3 1 0.9
apply --scale
material assign Rock
active Rock
mode edit
select face where "normal.z > 0.5"
material assign Top
mode object
shade flat
export rock.glb
""")

# ---- kelp: a stalk of five leaning segments and two leaves, 2.4 m (it sways: the bake's "sway" flag)
k = ["# Kelp: five mint segments zig-zagging up 2.4 m, two leaves. Generated by make_env.py.", "new",
     mat("Kelp", "mint"), mat("Stem", "teal")]
x = 0.0
for i in range(5):
    lean = 12 if i % 2 == 0 else -12
    k += box(f"Seg{i}", x, 0, 0.25 + i * 0.48, 0.14, 0.1, 0.52, "Kelp" if i % 2 else "Stem", rot=f"0 {lean} 0")
    x += 0.1 if i % 2 == 0 else -0.1
k += box("LeafA", 0.22, 0, 1.0, 0.36, 0.06, 0.16, "Kelp", rot="0 -30 0")
k += box("LeafB", -0.2, 0, 1.75, 0.34, 0.06, 0.15, "Kelp", rot="0 30 0")
k += ["select all", "shade flat", "export kelp.glb"]
open("kelp.txt", "w").write("\n".join(k) + "\n")

open("island.txt", "w").write(f"""# A far islet on the horizon: a low faceted hill and a striped lighthouse with a lit lamp.
# Origin at the water line under the hill. Generated by make_env.py.
new
{mat("Hill", "berry")}
{mat("Tower", "cream")}
{mat("Stripe", "rose")}
{mat("Lamp", "gold", True)}
add mesh cone --name Hill --vertices 7 --radius1 2.4 --radius2 0.6 --depth 1.0 --location 0 0 0.3
scale 1 0.5 1
apply --scale
material assign Hill
add mesh cone --name Tower --vertices 6 --radius1 0.32 --radius2 0.22 --depth 1.6 --location 0.4 0 1.6
material assign Tower
add mesh cylinder --name Band --vertices 6 --radius 0.3 --depth 0.25 --location 0.4 0 1.5
material assign Stripe
add mesh cube --name Lamp --size 0.3 --location 0.4 0 2.52
material assign Lamp
add mesh cone --name Cap --vertices 6 --radius1 0.28 --radius2 0 --depth 0.3 --location 0.4 0 2.8
material assign Stripe
select all
shade flat
export island.glb
""")

